package com.littlemakers.village.nativeapp;
public final class NavigationTest {public static void main(String[]args){if(NavigationPolicy.back("game","native-count-1")!=NavigationPolicy.Destination.CATALOG)throw new AssertionError("Game Back");for(String screen:new String[]{"catalog","shop","privacy","parent"})if(NavigationPolicy.back(screen,null)!=NavigationPolicy.Destination.HOME)throw new AssertionError(screen);if(NavigationPolicy.back("home",null)!=NavigationPolicy.Destination.EXIT)throw new AssertionError("Home Back");for(GameCatalog.Kind kind:GameCatalog.Kind.values()){boolean tactile=kind==GameCatalog.Kind.TRACE;if(GesturePolicy.capture(kind,"")!=tactile)throw new AssertionError("Scroll blocked: "+kind);}if(!GesturePolicy.capture(GameCatalog.Kind.SHAPES,"choose")||!GesturePolicy.capture(GameCatalog.Kind.COLORS,"match"))throw new AssertionError("Tactile drag not captured");System.out.println("PASS: shared legacy/predictive Back routing for all native destinations; tap games allow scrolling and tactile gestures stay captured.");}}
